CREATE TABLE whatsapp_status_notices (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, order_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, state VARCHAR(24) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'queued', details JSON NULL, channel VARCHAR(16) NULL, error VARCHAR(500) NULL, conversation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, message_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), sent_at DATETIME(6) NULL, updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY whatsapp_status_notices_order_state_uq (order_id,state), KEY whatsapp_status_notices_queue_idx (status,created_at), CONSTRAINT whatsapp_status_notices_state_ck CHECK (state IN ('guide_generated','in_transit','novelty','delivered')), CONSTRAINT whatsapp_status_notices_status_ck CHECK (status IN ('queued','sending','sent','skipped','failed')), CONSTRAINT whatsapp_status_notices_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT whatsapp_status_notices_order_fk FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci